// The single function replacing the copy-pasted "build history + build system
// instruction" block that used to appear separately in handleSend,
// handleEditMessage, and handleRegenerate.
// Each scene note and how much it matters when space runs short (#187):
// 5 = never dropped (rules and what's true), 1 = first to go.
const NOTE_PRIORITY: [keyof SceneContext, NotePriority][] = [
  ["knowsNote", 2], ["tiesNote", 3], ["worldTalkNote", 3], ["groupsNote", 4], ["letterNote", 4], ["onThisDayNote", 2], ["giftsNote", 3], ["plansNote", 3], ["secretsNote", 3],
  ["godNote", 5], ["eventNote", 4], ["arcNote", 4], ["historyNote", 2], ["heardNote", 3], ["goalNote", 3], ["youAtNote", 4], ["keptNote", 4], ["factionNote", 3], ["lifeNote", 4], ["reputationNote", 3], ["canonNote", 5], ["worldNowNote", 3], ["innerNote", 3], ["pointsNote", 4],
  ["whatIfNote", 5], ["dayNote", 4], ["dayMoodNote", 4], ["moodNote", 4], ["jokesNote", 3], ["conflictNote", 5], ["liesNote", 4], ["jealousyNote", 3], ["dreamNote", 5],
  ["hookNote", 5], ["slipsNote", 5], ["callbackNote", 4], ["concernsNote", 3], ["placeNote", 3], ["statusNote", 4], ["quoteNote", 5], ["groupNote", 5], ["profileNote", 2],
  ["disappearingNote", 5], ["inviteNote", 5], ["stickerNote", 5], ["blockNote", 5], ["timePassedNote", 5],
];

const budgetedNotes = (scene: SceneContext | undefined): string[] => {
  if (!scene) return [];
  const notes = NOTE_PRIORITY.flatMap(([key, priority]) => (typeof scene[key] === "string" && scene[key] ? [{ key: String(key), text: scene[key] as string, priority }] : []));
  const { kept, dropped } = fitNotes(notes, scene.noteBudget);
  recordDropped(dropped);
  return kept.map((n) => n.text);
};

export const buildTurnContext = (
  fullMessages: Message[],
  character: Character | undefined,
  extraDirectives?: string[],
  replyLengthLimit?: number,
  activePersona?: UserProfile,
  roomContext?: RoomContext,
  scene?: SceneContext
): TurnContext => {
  // Messages an earlier compression already summarized stay in the chat but
  // aren't sent: the model sees the seed, then the newest summary onward.
  const messages = trimToLatestSummary(fullMessages);
  const perspective = roomContext && character ? { selfId: character.id, userName: activePersona?.name?.trim() || "User" } : undefined;
  const history = buildChatHistory(messages, roomContext?.speakerNames, perspective);
  // The story script (#57) goes in the system instruction, which is never
  // compressed, so it holds however long the chat runs.
  // A mini-game's rules (#52) ride along the same way while it's on.
  const sceneDirectives = [
    ...(scene?.storyScript ? [buildStoryScriptSection(scene.storyScript)] : []),
    ...(scene?.game && character ? [buildGameSection(scene.game, character.name)] : []),
    ...(scene?.onCall && character ? [buildCallSection(character.name)] : []),
    ...(scene?.sceneTracker && character ? [buildStateDirective(scene.sceneState, character.name, scene.roomNames, scene.meters)] : []),
    ...(scene?.boldness && character ? [buildBoldnessSection(scene.boldness, character.name)] : []),
    // The intimacy profile (#73) only once the scene turns romantic.
    ...(character && intimacyInScope(scene?.stage, fullMessages) ? [buildIntimacySection(character, activePersona)].filter((x): x is string => Boolean(x)) : []),
    ...(scene?.choiceMoments ? [CHOICE_MOMENT_DIRECTIVE] : []),
    // The notes, within the prompt budget (#187).
    ...budgetedNotes(scene),
    ...(scene?.language ? [buildLanguageDirective(scene.language, activePersona?.name?.trim() || "The user")] : []),
    ...(scene?.coWriting && character ? [buildCoWritingDirective(character.name, activePersona?.name?.trim() || "the user")] : []),
    ...(scene?.stage ? [buildStageSection(scene.stage, activePersona?.name?.trim() || "the user")] : []),
  ];
  const directives = sceneDirectives.length > 0 ? [...sceneDirectives, ...(extraDirectives || [])] : extraDirectives;
  const { text, images, characterName } = buildSystemInstruction(
    character, directives, replyLengthLimit, activePersona, messages, roomContext?.otherParticipants,
    roomContext?.groupScenario, roomContext?.groupMemory,
    {
      roleplayStyle: scene?.roleplayStyle,
      worldTags: scene?.worldTags,
      roomLoreEntries: roomContext?.otherLoreEntries,
      groupPinnedMemory: roomContext?.groupPinnedMemory,
      groupStanding: roomContext?.groupStanding,
      roomAllowsNsfw: roomContext?.othersAllowNsfw,
      memoryOverride: scene?.memoryOverride,
      world: scene?.world,
      roomRelationshipNotes: roomContext?.relationshipNotes,
      roomThoughts: roomContext?.thoughts,
      roomOffscreenTalk: roomContext?.offscreenTalk,
      roomOthersAbout: roomContext?.othersAbout,
      roomSpeakerNotes: roomContext?.speakerNotes,
      emotionTag: scene?.moodCarry,
      memoryDates: scene?.memoryDates,
      misremembers: scene?.misremembers,
    }
  );
  // The active persona's own reference photos (UserProfile.appearanceImages),
  // folded in as just another named reference alongside any other room
  // participants - so "a picture of us together" keeps the user's face
  // consistent too, in a 1:1 chat as much as a room. Unset when the persona
  // has none, so behavior is unchanged for everyone who hasn't added any.
  const personaReference = activePersona?.appearanceImages && activePersona.appearanceImages.length > 0
    ? { name: activePersona.name, images: activePersona.appearanceImages }
    : undefined;
  const otherParticipantImages = personaReference
    ? [...(roomContext?.otherParticipantImages || []), personaReference]
    : roomContext?.otherParticipantImages;
  return {
    history,
    systemInstruction: text,
    postHistoryNote: buildPostHistoryNote(character, scene?.authorNote, activePersona, {
      hardLimits: scene?.hardLimits,
      intensity: scene?.intensity,
      nsfwActive: effectiveContentRating(character) === "nsfw" && (!roomContext || Boolean(roomContext.othersAllowNsfw)),
      avoidNote: scene?.roleplayStyle?.antiRepetition === false ? undefined : avoidNoteFor(messages, character),
    }),
    characterImages: images,
    characterName,
    otherParticipantImages,
    protectedCount: countProtectedPrefix(messages),
    appearanceLocks: [...appearanceLocksFor(character ? [character] : []), ...(roomContext?.otherAppearanceLocks || [])],
  };
};
